package controlador;
import java.io.IOException; import jakarta.servlet.*; import jakarta.servlet.http.*; import modelo.Cita; import modelo.CitaDAO;
public class CtrolCita extends HttpServlet{protected void processRequest(HttpServletRequest request,HttpServletResponse response)throws ServletException,IOException{request.setCharacterEncoding("UTF-8"); HttpSession ses=request.getSession(); String cliente=(String)ses.getAttribute("idUsuario"); Cita c=new Cita(); c.setIdentificacionCliente(cliente); c.setIdentificacionDoctor(request.getParameter("identificacion_doctor")); c.setIdServicio(Integer.parseInt(request.getParameter("id_servicio"))); c.setFecha(request.getParameter("fecha")); c.setHora(request.getParameter("hora")); c.setObservacion(request.getParameter("observacion")); int ok=new CitaDAO().agregar(c); response.sendRedirect(ok>0?"misCitasCliente.jsp":"agendarCita.jsp?error=1");} @Override protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{processRequest(r,s);} @Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{s.sendRedirect("agendarCita.jsp");}}
